<?php
 namespace Pterodactyl\Services\Dezerx\Minecraft; use Illuminate\Support\Facades\Cache; class PlayerRoster { public const UUID = '/^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/'; private const MAX_LOG = 4_000_000; private const NAMES_TTL = 30; public static function list(ServerFiles $files, string $server): array { $saved = []; foreach ($files->listFiles(PlayerFiles::dirs($files, $server)['data']) ?? [] as $entry) { $name = (string) ($entry['name'] ?? ''); if (!str_ends_with($name, '.dat')) { continue; } $uuid = strtolower(substr($name, 0, -4)); if (preg_match(self::UUID, $uuid) === 1) { $saved[$uuid] = $entry['modified_at'] ?? null; } } $names = self::names($files, $server); $online = self::online($files, $server); $ops = self::uuidsIn($files, '/ops.json'); $banned = self::uuidsIn($files, '/banned-players.json'); $whitelisted = self::uuidsIn($files, '/whitelist.json'); $players = []; foreach ($names + array_fill_keys(array_keys($saved), null) as $uuid => $name) { $players[] = [ 'uuid' => $uuid, 'name' => $name, 'lastSeen' => $saved[$uuid] ?? null, 'hasData' => array_key_exists($uuid, $saved), 'online' => $name !== null && isset($online[strtolower($name)]), 'op' => isset($ops[$uuid]), 'banned' => isset($banned[$uuid]), 'whitelisted' => isset($whitelisted[$uuid]), ]; } usort($players, function (array $a, array $b) { if ($a['online'] !== $b['online']) { return $a['online'] ? -1 : 1; } return strcmp((string) ($b['lastSeen'] ?? ''), (string) ($a['lastSeen'] ?? '')); }); return $players; } public static function names(ServerFiles $files, string $server): array { return Cache::remember( "dezerx:playernames:{$server}", self::NAMES_TTL, fn () => self::readNames($files), ); } private static function readNames(ServerFiles $files): array { $names = []; $raw = $files->fileContents('/usercache.json'); $entries = $raw === null ? null : json_decode($raw, true); if (is_array($entries)) { foreach ($entries as $entry) { if (!is_array($entry)) { continue; } $uuid = strtolower((string) ($entry['uuid'] ?? '')); $name = (string) ($entry['name'] ?? ''); if ($uuid !== '' && $name !== '') { $names[$uuid] = $name; } } } $raw = $files->fileContents('/usernamecache.json'); $entries = $raw === null ? null : json_decode($raw, true); if (is_array($entries)) { foreach ($entries as $uuid => $name) { $uuid = strtolower((string) $uuid); if (!is_string($name) || $name === '' || isset($names[$uuid]) || preg_match(self::UUID, $uuid) !== 1) { continue; } $names[$uuid] = $name; } } return $names; } public static function online(ServerFiles $files, string $server): array { return self::onlineOrNull($files, $server) ?? []; } public static function onlineOrNull(ServerFiles $files, string $server): ?array { $size = null; foreach ($files->listFiles('/logs') ?? [] as $entry) { if (($entry['name'] ?? '') === 'latest.log') { $size = (int) ($entry['size'] ?? 0); } } if ($size === null || $size > self::MAX_LOG) { return null; } $log = $files->fileContents('/logs/latest.log'); if ($log === null) { return null; } $state = []; if (preg_match_all( '/^\[[^\]]+\](?: \[[^\]]+\])*: ([A-Za-z0-9_]{1,16}) (joined|left) the game\r?$/m', $log, $matches, PREG_SET_ORDER, ) === false) { return null; } foreach ($matches as $match) { $state[strtolower($match[1])] = $match[2] === 'joined'; } return array_filter($state); } public static function levelName(ServerFiles $files, string $server): string { return Cache::remember("dezerx:playerlevel:{$server}", self::NAMES_TTL, function () use ($files) { $fromProps = self::levelFromProperties($files); foreach (array_values(array_unique(array_filter([$fromProps, 'world']))) as $candidate) { if (self::looksLikeLevel($files, $candidate)) { return $candidate; } } foreach ($files->listFiles('/') ?? [] as $entry) { if (!($entry['directory'] ?? false)) { continue; } $name = (string) ($entry['name'] ?? ''); if ($name === '' || str_contains($name, '/') || str_contains($name, '..')) { continue; } if (self::looksLikeLevel($files, $name)) { return $name; } } return $fromProps ?? 'world'; }); } private static function levelFromProperties(ServerFiles $files): ?string { $raw = $files->fileContents('/server.properties'); if ($raw === null) { return null; } foreach (preg_split('/\r?\n/', $raw) ?: [] as $line) { if (str_starts_with(ltrim($line), 'level-name=')) { $value = trim(substr(ltrim($line), 11)); if ($value === '' || str_contains($value, '/') || str_contains($value, '..')) { return null; } return $value; } } return null; } private static function looksLikeLevel(ServerFiles $files, string $level): bool { $players = $files->listFiles("/{$level}/playerdata"); if (is_array($players) && $players !== []) { return true; } foreach ($files->listFiles("/{$level}") ?? [] as $entry) { if (($entry['name'] ?? '') === 'level.dat') { return true; } } return is_array($files->listFiles("/{$level}/players/data")); } public static function uuidsIn(ServerFiles $files, string $file): array { $raw = $files->fileContents($file); $entries = $raw === null ? null : json_decode($raw, true); if (!is_array($entries)) { return []; } $found = []; foreach ($entries as $entry) { $uuid = is_array($entry) ? strtolower((string) ($entry['uuid'] ?? '')) : ''; if ($uuid !== '') { $found[$uuid] = true; } } return $found; } public static function forget(string $server, ?string $uuid = null): void { Cache::forget("dezerx:players:{$server}"); Cache::forget("dezerx:playernames:{$server}"); Cache::forget("dezerx:playerlevel:{$server}"); Cache::forget("dezerx:playerlayout:{$server}"); if ($uuid !== null) { Cache::forget("dezerx:player:{$server}:{$uuid}"); Cache::forget("dezerx:playerstats:{$server}:{$uuid}"); } } } 